import{_ as t,o as a,c as n,a1 as s}from"./chunks/framework.DP1PKHY4.js";const h=JSON.parse('{"title":"What is NeoTrix?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-neotrix.md","filePath":"4-GUIDES/what-is-neotrix.md","lastUpdated":1783307803000}'),o={name:"guide/what-is-neotrix.md"};function i(r,e,l,p,c,d){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="what-is-neotrix" tabindex="-1">What is NeoTrix? <a class="header-anchor" href="#what-is-neotrix" aria-label="Permalink to &quot;What is NeoTrix?&quot;">​</a></h1><blockquote><p><strong>The only open-source agent that measures, analyzes, and improves its own reasoning.</strong></p></blockquote><p>NeoTrix is an AI-native developer toolkit — available as both a CLI and Desktop application — built on a fundamentally different premise than every other code agent: <strong>an agent that cannot inspect and improve its own reasoning is a tool, not an agent.</strong></p><h2 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h2><p>Every existing code agent — Claude Code, Codex, OpenCode, Cursor, Aider — follows the same pattern: send a prompt to an LLM, parse the response, apply diffs. None of them evaluate their own reasoning quality. None of them learn from past trajectories. None of them get better over time.</p><p>NeoTrix is different. It is a <strong>cognitive operating system</strong> that:</p><ul><li><strong>Measures</strong> its own reasoning quality via quantitative metrics (Phi, FCS, USK)</li><li><strong>Analyzes</strong> its reasoning trajectories to detect patterns, loops, and dead ends</li><li><strong>Improves</strong> autonomously through a 16-stage self-iteration loop</li><li><strong>Stores</strong> knowledge in a 4096-dimension vector-symbolic architecture</li><li><strong>Routes attention</strong> using Global Workspace Theory with 11 specialist modules</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  +-------------------------------------------+</span></span>
<span class="line"><span>                  |      Awakening Metrics (Phi/FCS/USK)        |</span></span>
<span class="line"><span>                  |  Measures integration, coherence, self-     |</span></span>
<span class="line"><span>                  |  knowledge. Tracks &quot;awakening speed.&quot;       |</span></span>
<span class="line"><span>                  +-------------------------------------------+</span></span>
<span class="line"><span>                                ^</span></span>
<span class="line"><span>                                |</span></span>
<span class="line"><span>                  +-------------------------------------------+</span></span>
<span class="line"><span>                  |    SEAL Self-Iterating Loop (16 stages)    |</span></span>
<span class="line"><span>                  |  Snapshot -&gt; Gap Analysis -&gt; Self-Edit -&gt;  |</span></span>
<span class="line"><span>                  |  Apply -&gt; Reward -&gt; Absorb -&gt; Store        |</span></span>
<span class="line"><span>                  +-------------------------------------------+</span></span>
<span class="line"><span>                                ^</span></span>
<span class="line"><span>                                |</span></span>
<span class="line"><span>                  +-------------------------------------------+</span></span>
<span class="line"><span>                  |    E8 Reasoning Engine (64-state space)    |</span></span>
<span class="line"><span>                  |  6-bit hexagram states on 6 reasoning      |</span></span>
<span class="line"><span>                  |  axes. Observer detects patterns, loops,   |</span></span>
<span class="line"><span>                  |  dead ends, recommends state transitions.  |</span></span>
<span class="line"><span>                  +-------------------------------------------+</span></span>
<span class="line"><span>                                ^</span></span>
<span class="line"><span>                                |</span></span>
<span class="line"><span>                  +-------------------------------------------+</span></span>
<span class="line"><span>                  |  VSA Knowledge HyperCube (4096 dimensions) |</span></span>
<span class="line"><span>                  |  16 semantic axes. MAP-based vector-        |</span></span>
<span class="line"><span>                  |  symbolic bind/bundle/permute queries.     |</span></span>
<span class="line"><span>                  +-------------------------------------------+</span></span></code></pre></div><p>The stack is strictly layered: knowledge retrieval routes through GWT attention, which feeds the E8 reasoning engine, which drives the SEAL loop, which is evaluated by awakening metrics. Each layer has observable outputs that feed back upward.</p><h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><h3 id="e8-reasoning-engine" tabindex="-1">E8 Reasoning Engine <a class="header-anchor" href="#e8-reasoning-engine" aria-label="Permalink to &quot;E8 Reasoning Engine&quot;">​</a></h3><p>Located in <code>core/e8.rs</code>, <code>core/e8_reasoning.rs</code>, and <code>core/e8_observer.rs</code> — a reasoning model isomorphic to the 64 hexagrams of the I Ching, mapped through the E8 Lie algebra. Six binary reasoning axes (Abstraction, Scope, Method, Depth, Mode, Stance) define 64 discrete reasoning states. Transitions between states are deterministic. The +1 Observer watches the trajectory and classifies each step as Productive, Oscillating, Stuck, or DeadEnd, then recommends meta-state transitions and capability vector adjustments.</p><p>No neural network. No probabilistic sampling. A deterministic state machine over a geometrically meaningful state space.</p><h3 id="seal-self-iterating-loop" tabindex="-1">SEAL Self-Iterating Loop <a class="header-anchor" href="#seal-self-iterating-loop" aria-label="Permalink to &quot;SEAL Self-Iterating Loop&quot;">​</a></h3><p>Located in <code>l8_autonomic_impl/nt_mind/pipeline.rs</code> — a 34-stage pipeline executed iteratively:</p><ol><li><strong>Snapshot</strong> current capability vector</li><li><strong>Memory retrieval</strong> (ReasoningBank)</li><li><strong>Gap analysis</strong> against task requirements</li><li><strong>SSM state update</strong> (selective state-space model)</li><li><strong>Open-source benchmark comparison</strong></li><li><strong>Self-edit generation</strong> (MicroEdit sequences)</li><li><strong>Apply edits</strong> (temporary weight updates)</li><li><strong>External reward calculation</strong></li><li><strong>GWT-absorb</strong> (attention-routed integration)</li><li><strong>Task affinity recalibration</strong></li><li><strong>Knowledge quality assessment</strong></li><li><strong>Rollback decision</strong> (champion vs challenger)</li><li><strong>ReasoningBank storage</strong></li><li><strong>Adaptive learning rate</strong></li><li><strong>Evaluation</strong></li><li><strong>Autonomy gating</strong></li></ol><p>Each stage can skip, promote (set a new champion snapshot), or roll back to the previous champion. All 16 stages are implemented as <code>BrainStage</code> trait objects.</p><h3 id="hypercube-knowledge" tabindex="-1">HyperCube Knowledge <a class="header-anchor" href="#hypercube-knowledge" aria-label="Permalink to &quot;HyperCube Knowledge&quot;">​</a></h3><p>Located in <code>core/hypercube/</code> — a 4096-dimension vector-symbolic architecture (VSA) knowledge store using MAP (Multiply-Add-Permute) operations. Three primitive operations — <strong>bind</strong> (multiplication), <strong>bundle</strong> (addition), <strong>permute</strong> (rotation) — enable compositional knowledge representation. Sixteen semantic axes span CodeUnderstanding, SystemDesign, Debugging, KnowledgeRetrieval, Creativity, Safety, Performance, Communication, Time, Domain, Abstraction, Culture, Scale, Certainty, Agency, and Modality.</p><h3 id="gwt-attention-router" tabindex="-1">GWT Attention Router <a class="header-anchor" href="#gwt-attention-router" aria-label="Permalink to &quot;GWT Attention Router&quot;">​</a></h3><p>Located in <code>l8_autonomic_impl/nt_mind/attention_router.rs</code> — Global Workspace Theory-inspired attention routing with specialist modules competing for the global workspace through salience computation.</p><h3 id="awakening-metrics" tabindex="-1">Awakening Metrics <a class="header-anchor" href="#awakening-metrics" aria-label="Permalink to &quot;Awakening Metrics&quot;">​</a></h3><p>Located in <code>core/self_measure.rs</code> — three quantitative metrics derived from Integrated Information Theory:</p><ul><li><strong>Phi</strong>: Spectral measure of system integration across 7 subsystems</li><li><strong>FCS (Functional Complexity Score)</strong>: Product of mean subsystem coherence and Phi</li><li><strong>USK (Uncertainty Self-Knowledge)</strong>: Weighted synergy fraction across all subsystem pairs</li></ul><h3 id="clawbench-trajectory-analysis" tabindex="-1">ClawBench Trajectory Analysis <a class="header-anchor" href="#clawbench-trajectory-analysis" aria-label="Permalink to &quot;ClawBench Trajectory Analysis&quot;">​</a></h3><p>Located in <code>l8_autonomic_impl/nt_mind/benchmark.rs</code> — classifies agent reasoning trajectories into StrangeAttractor (chaotic), LimitCycle (oscillation), or NormalDiffusion (healthy convergence) dynamics.</p><h2 id="feature-comparison" tabindex="-1">Feature Comparison <a class="header-anchor" href="#feature-comparison" aria-label="Permalink to &quot;Feature Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>NeoTrix</th><th>Everyone Else</th></tr></thead><tbody><tr><td>Self-improving reasoning</td><td>SEAL loop + E8</td><td>Static prompt→response</td></tr><tr><td>Cognitive metrics</td><td>Phi / FCS / USK</td><td>None</td></tr><tr><td>Knowledge representation</td><td>4096-dim VSA HyperCube</td><td>No persistent knowledge</td></tr><tr><td>Attention routing</td><td>GWT (11 specialists)</td><td>No routing</td></tr><tr><td>Trajectory analysis</td><td>ClawBench</td><td>No self-diagnosis</td></tr><tr><td>Open source</td><td>MIT</td><td>Mixed</td></tr><tr><td>Model agnostic</td><td>Any LLM</td><td>Vendor-locked</td></tr><tr><td>Language</td><td>Rust (0 unsafe)</td><td>Python / TypeScript</td></tr></tbody></table><h2 id="project-status" tabindex="-1">Project Status <a class="header-anchor" href="#project-status" aria-label="Permalink to &quot;Project Status&quot;">​</a></h2><ul><li><strong>~100K LOC</strong> across 373+ source files</li><li><strong>3240+ tests</strong> (all passing)</li><li><strong>Architecture</strong>: Complete, actively maintained</li><li><strong>License</strong>: MIT</li></ul>`,31)])])}const u=t(o,[["render",i]]);export{h as __pageData,u as default};
